/**
 * Joi validation schema for the `project` JSONB column in bng.projects.
 *
 * Generated by /reflect-schema from a sample row. Update by re-running the
 * skill after schema changes, or edit manually as requirements become clearer.
 *
 * The `.description()` on every key is the source of prose for the generated
 * data dictionary (`npm run data-dictionary` → docs/data-dictionary.md) and for
 * the Swagger UI. Keep them accurate: they document what is actually persisted.
 */
import Joi from 'joi'

import { MAX_FILE_SIZE_BYTES } from '../services/s3/download-file.js'

const MAX_FILENAME_LENGTH = 255

// Whitelist-only approach addresses six classes of attack in one rule:
//   1. Extension spoofing  — bidi overrides (U+202E etc.) not in [a-zA-Z0-9 ._-]
//   2. Path traversal      — / and leading dots excluded; .. sequences impossible
//   3. Log injection       — \n, \r and other control chars not in the set
//   4. Wrong extension     — \.gpkg$ is mandatory (case-insensitive)
//   5. Invisible chars      — zero-width / formatting codepoints not in the set
//   6. SQL injection       — ' " ; not in the set; lone - cannot form --
const SAFE_FILENAME_RE = /^[a-z0-9][a-z0-9 ._-]*\.gpkg$/i

const siteSchema = Joi.object({
  name: Joi.string().description('Free-text name of the development site.'),
  grid_ref: Joi.string().description(
    'Ordnance Survey national grid reference for the site.'
  )
}).description('Development site details.')

const unitsSchema = Joi.object({
  habitat: Joi.number().description(
    'Project-level area-habitat biodiversity unit total.'
  ),
  hedgerow: Joi.number().description(
    'Project-level hedgerow biodiversity unit total.'
  ),
  watercourse: Joi.number().description(
    'Project-level watercourse biodiversity unit total.'
  )
}).description('Project-level biodiversity unit summary.')

const habitatSizesSummarySchema = Joi.object({
  areaHabitats: Joi.object({
    totalSquareMetres: Joi.number()
      .required()
      .description('Total area of all habitat parcels, in square metres.')
  }).required(),
  hedgerows: Joi.object({
    totalMetres: Joi.number()
      .required()
      .description('Total length of all hedgerows, in metres.')
  }).required(),
  watercourses: Joi.object({
    totalMetres: Joi.number()
      .required()
      .description('Total length of all watercourses, in metres.')
  }).required()
})
  .allow(null)
  .description(
    'Total feature sizes by module, measured from geometry in PostGIS. Null until a baseline is imported.'
  )

const baselineUnitsTotalsSchema = Joi.object({
  totalUnits: Joi.number()
    .required()
    .description('Sum of habitat, hedgerow and watercourse baseline units.'),
  habitatsTotal: Joi.number()
    .required()
    .description('Sum of baseline units across all area habitats.'),
  hedgerowsTotal: Joi.number()
    .required()
    .description('Sum of baseline units across all hedgerows.'),
  watercoursesTotal: Joi.number()
    .required()
    .description('Sum of baseline units across all watercourses.')
}).description('Baseline biodiversity unit totals, summed across features.')

const redLineSchema = Joi.object({
  featureId: Joi.string()
    .uuid()
    .required()
    .description(
      'UUID assigned on import; join key to the bng.baseline_red_line geometry row.'
    ),
  properties: Joi.object()
    .unknown(true)
    .description(
      'Raw attribute columns copied verbatim from the GeoPackage Red Line Boundary layer.'
    )
})
  .allow(null)
  .description(
    'Red Line Boundary feature defining the site extent. Null until a baseline is imported.'
  )

const habitatSchema = Joi.object({
  featureId: Joi.string()
    .uuid()
    .required()
    .description(
      'UUID assigned on import; join key to the bng.baseline_habitats geometry row.'
    ),
  ref: Joi.string()
    .allow(null, '')
    .description('Parcel reference from the GeoPackage (Parcel Ref column).'),
  type: Joi.string()
    .allow(null, '')
    .description("Baseline habitat type, e.g. 'Lowland meadows'."),
  broadType: Joi.string()
    .allow(null, '')
    .description("Baseline broad habitat type, e.g. 'Grassland'."),
  distinctiveness: Joi.string()
    .allow(null, '')
    .description(
      "Distinctiveness band resolved by bng-metric-engine from the habitat type, e.g. 'High'. Set once the habitat type is recognised."
    ),
  distinctivenessScore: Joi.number()
    .allow(null)
    .description(
      'Numeric distinctiveness score for the band, from bng-metric-engine.'
    ),
  condition: Joi.string()
    .allow(null, '')
    .description("Baseline condition assessment, e.g. 'Good'."),
  conditionScore: Joi.number()
    .allow(null)
    .description(
      'Numeric condition score from bng-metric-engine. Set during import enrichment and on habitat edits.'
    ),
  strategicSignificance: Joi.string()
    .allow(null, '')
    .description('Strategic significance category from the GeoPackage.'),
  retentionCategory: Joi.string()
    .allow(null, '')
    .description('Retention category from the GeoPackage.'),
  area: Joi.number()
    .allow(null)
    .description(
      'Parcel area in square metres, measured in PostGIS and rounded to the nearest integer. This is the value fed to the unit calculation.'
    ),
  sizeSquareMetres: Joi.number()
    .allow(null)
    .description('Exact parcel area in square metres as measured in PostGIS.'),
  status: Joi.string()
    .valid('Complete', 'Incomplete')
    .required()
    .description(
      "'Complete' when broad type, habitat type and condition are all set; otherwise 'Incomplete'."
    ),
  units: Joi.number()
    .allow(null)
    .description(
      'Baseline biodiversity units for the parcel. Written by both the import/enrichment path and the habitat-edit endpoint; read by the frontend display and the baseline unit totals.'
    ),
  properties: Joi.object()
    .unknown(true)
    .description(
      'Raw attribute columns copied verbatim from the GeoPackage Habitats layer.'
    )
}).description('An area (polygon) habitat parcel.')

const linearHabitatSchema = Joi.object({
  featureId: Joi.string()
    .uuid()
    .required()
    .description(
      'UUID assigned on import; join key to the bng.baseline_hedgerows geometry row.'
    ),
  ref: Joi.string()
    .allow(null, '')
    .description('Feature reference from the GeoPackage (Parcel Ref column).'),
  type: Joi.string()
    .allow(null, '')
    .description('Hedgerow type (Baseline Hedge Type column).'),
  condition: Joi.string()
    .allow(null, '')
    .description('Hedgerow condition assessment.'),
  distinctiveness: Joi.string()
    .allow(null, '')
    .description(
      'Distinctiveness band resolved by bng-metric-engine from the hedgerow type.'
    ),
  distinctivenessScore: Joi.number()
    .allow(null)
    .description(
      'Numeric distinctiveness score for the band, from bng-metric-engine.'
    ),
  conditionScore: Joi.number()
    .allow(null)
    .description('Numeric condition score from bng-metric-engine.'),
  length: Joi.number()
    .allow(null)
    .description(
      'Length in metres (PostGIS size, rounded). Set during unit enrichment.'
    ),
  sizeMetres: Joi.number()
    .allow(null)
    .description('Length in metres as measured in PostGIS.'),
  status: Joi.string()
    .valid('Complete', 'Incomplete')
    .required()
    .description(
      "'Complete' when type and condition are both set; otherwise 'Incomplete'."
    ),
  units: Joi.number()
    .allow(null)
    .description(
      'Baseline biodiversity units for the hedgerow, from bng-metric-engine (BMD-427/428).'
    ),
  properties: Joi.object()
    .unknown(true)
    .description(
      'Raw attribute columns copied verbatim from the GeoPackage Hedgerows layer.'
    )
}).description('A hedgerow (linear) feature.')

const watercourseHabitatSchema = Joi.object({
  featureId: Joi.string()
    .uuid()
    .required()
    .description(
      'UUID assigned on import; join key to the bng.baseline_watercourses geometry row.'
    ),
  ref: Joi.string()
    .allow(null, '')
    .description('Feature reference from the GeoPackage (Parcel Ref column).'),
  type: Joi.string()
    .allow(null, '')
    .description('Watercourse type (Baseline River Type column).'),
  condition: Joi.string()
    .allow(null, '')
    .description('Watercourse condition assessment.'),
  riparianEncroachment: Joi.string()
    .allow(null, '')
    .description('Riparian-zone encroachment category from the GeoPackage.'),
  watercourseEncroachment: Joi.string()
    .allow(null, '')
    .description('Watercourse encroachment category from the GeoPackage.'),
  distinctiveness: Joi.string()
    .allow(null, '')
    .description(
      'Distinctiveness band resolved by bng-metric-engine from the watercourse type.'
    ),
  distinctivenessScore: Joi.number()
    .allow(null)
    .description(
      'Numeric distinctiveness score for the band, from bng-metric-engine.'
    ),
  conditionScore: Joi.number()
    .allow(null)
    .description('Numeric condition score from bng-metric-engine.'),
  length: Joi.number()
    .allow(null)
    .description(
      'Length in metres (PostGIS size, rounded). Set during unit enrichment.'
    ),
  sizeMetres: Joi.number()
    .allow(null)
    .description('Length in metres as measured in PostGIS.'),
  status: Joi.string()
    .valid('Complete', 'Incomplete')
    .required()
    .description(
      "'Complete' when type, condition, riparian encroachment and watercourse encroachment are all set; otherwise 'Incomplete'."
    ),
  units: Joi.number()
    .allow(null)
    .description(
      'Baseline biodiversity units for the watercourse, from bng-metric-engine (BMD-427/428).'
    ),
  waterEncroachmentMultiplier: Joi.number()
    .allow(null)
    .description(
      'Watercourse-encroachment multiplier applied by bng-metric-engine when computing units.'
    ),
  riparianEncroachmentMultiplier: Joi.number()
    .allow(null)
    .description(
      'Riparian-encroachment multiplier applied by bng-metric-engine when computing units.'
    ),
  properties: Joi.object()
    .unknown(true)
    .description(
      'Raw attribute columns copied verbatim from the GeoPackage Watercourses layer.'
    )
}).description('A watercourse (linear) feature.')

const baselineSchema = Joi.object({
  uploadId: Joi.string()
    .uuid()
    .allow(null)
    .description(
      'CDP Uploader upload ID for the source GeoPackage. Null until a baseline is imported.'
    ),
  filename: Joi.string()
    .max(MAX_FILENAME_LENGTH)
    .pattern(SAFE_FILENAME_RE)
    .allow(null)
    .description(
      'Original filename of the uploaded baseline GeoPackage. Constrained to a safe `*.gpkg` pattern.'
    ),
  fileSize: Joi.number()
    .integer()
    .min(0)
    .max(MAX_FILE_SIZE_BYTES)
    .allow(null)
    .description('Size of the uploaded GeoPackage, in bytes.'),
  importedAt: Joi.string()
    .isoDate()
    .description('ISO 8601 timestamp of when the baseline was imported.'),
  redLine: redLineSchema,
  habitats: Joi.array()
    .items(habitatSchema)
    .description('Area (polygon) habitat parcels in the baseline.'),
  hedgerows: Joi.array()
    .items(linearHabitatSchema)
    .description('Hedgerow (linear) features in the baseline.'),
  watercourses: Joi.array()
    .items(watercourseHabitatSchema)
    .description('Watercourse (linear) features in the baseline.'),
  habitatSizes: habitatSizesSummarySchema,
  units: baselineUnitsTotalsSchema
}).description(
  'Imported baseline state: features, sizes and unit totals. Written by the baseline upload flow.'
)

const projectSchema = Joi.object({
  name: Joi.string().description(
    'Project name shown to the user; editable via PATCH /projects/{id}.'
  ),
  site: siteSchema,
  units: unitsSchema,
  baseline: baselineSchema
}).description(
  'Root document stored in the bng.projects.project JSONB column (and snapshotted into bng.audit_log.project).'
)

export {
  projectSchema,
  siteSchema,
  unitsSchema,
  baselineUnitsTotalsSchema,
  baselineSchema,
  habitatSchema,
  linearHabitatSchema,
  watercourseHabitatSchema
}
